<script>document.addEventListener('DOMContentLoaded',()=>{
const filter=document.getElementById('stock-filter');filter?.addEventListener('input',()=>{const q=filter.value.toLocaleLowerCase('tr-TR').trim();document.querySelectorAll('#stock-table tbody tr[data-search]').forEach(r=>r.hidden=!r.dataset.search.includes(q))});
const sourceBox=document.querySelector('.source-panel form[action*="urun-kaynaklari"] .source-urls');if(sourceBox){const fields=[...sourceBox.querySelectorAll('input[name="adresler[]"]')];fields.slice(1).forEach(x=>x.remove());const add=document.createElement('button');add.type='button';add.className='btn btn-outline-primary mt-2';add.innerHTML='<i class="bi bi-plus-lg"></i> Yeni Kaynak Satırı Aç';sourceBox.after(add);add.addEventListener('click',()=>{if(sourceBox.querySelectorAll('input').length>=50)return;const row=document.createElement('div');row.className='source-url-row';row.innerHTML='<input class="form-control" type="url" name="adresler[]" placeholder="http://.../GetProductsPart" required><button class="btn btn-outline-danger" type="button" aria-label="Satırı kaldır"><i class="bi bi-x-lg"></i></button>';row.querySelector('button').onclick=()=>row.remove();sourceBox.appendChild(row);row.querySelector('input').focus()})}
const depo=document.querySelector('select[name="depo_id"]'),raf=document.querySelector('select[name="depo_raf_id"]');if(depo&&raf){[...raf.options].forEach(o=>{if(o.value){const item=@json($raflar->mapWithKeys(fn($r)=>[$r->id=>$r->depo_id]));o.dataset.depo=item[o.value]||''}});const yenile=()=>{[...raf.options].forEach(o=>{if(o.value)o.hidden=o.dataset.depo!==depo.value});if(raf.selectedOptions[0]?.hidden)raf.value=''};depo.addEventListener('change',yenile);yenile()}
const product=document.getElementById('manage-product'),edit=document.getElementById('manage-product-edit'),del=document.getElementById('manage-product-delete');const syncProduct=()=>{const id=product?.value||'';if(edit)edit.disabled=!id;if(del){del.style.display=id?'block':'none';del.action=id?`{{ url('/depo/parcalar') }}/${id}`:''}};product?.addEventListener('change',syncProduct);edit?.addEventListener('click',()=>{if(product.value)location.href=`{{ route('depo.index',['firma_id'=>$firmaId]) }}&duzenle_parca=${product.value}#parca-duzenle`});syncProduct();
const ids=@json($parcalar->pluck('id')->values());const head=document.querySelector('#stock-table thead tr');if(head){const th=document.createElement('th');th.textContent='İşlem';head.appendChild(th)}document.querySelectorAll('#stock-table tbody tr[data-search]').forEach((row,i)=>{const id=ids[i],cell=document.createElement('td');cell.dataset.label='İşlem';cell.innerHTML=`<div class="stock-actions"><a class="btn btn-sm btn-outline-primary" href="{{ route('depo.index',['firma_id'=>$firmaId]) }}&duzenle_parca=${id}#parca-duzenle"><i class="bi bi-pencil"></i> Düzenle</a><form method="POST" action="{{ url('/depo/parcalar') }}/${id}" onsubmit="return confirm('Ürün kartı silinsin mi?')"><input type="hidden" name="_token" value="{{ csrf_token() }}"><input type="hidden" name="_method" value="DELETE"><input type="hidden" name="firma_id" value="{{ $firmaId }}"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash3"></i> Sil</button></form></div>`;row.appendChild(cell)});
})</script>
@endsection
